package sink

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/stellar-optics/stellar-prism/pkg/stream"
)

const (
	defaultTelegramEndpoint   = "https://api.telegram.org/bot%s/sendMessage"
	defaultTelegramTimeout    = 10 * time.Second
	defaultTelegramMaxRetries = 3
	defaultTelegramQueueSize  = 256
)

// AlertNotification represents a standardized alert generated by a rule.
type AlertNotification struct {
	RuleName   string                 `json:"rule_name"`
	Severity   string                 `json:"severity"`
	LedgerSeq  uint32                 `json:"ledger_seq"`
	TxHash     string                 `json:"tx_hash,omitempty"`
	ContractID string                 `json:"contract_id,omitempty"`
	EventIndex uint32                 `json:"event_index,omitempty"`
	Message    string                 `json:"message"`
	Details    map[string]interface{} `json:"details,omitempty"`
	Timestamp  time.Time              `json:"timestamp"`
}

// TelegramOptions configures the Telegram alert dispatcher.
type TelegramOptions struct {
	Token      string
	ChatID     string
	Endpoint   string
	Client     *http.Client
	Timeout    time.Duration
	MaxRetries int
	QueueSize  int
}

// TelegramSink dispatches alert messages to a Telegram chat.
type TelegramSink struct {
	opts    TelegramOptions
	client  *http.Client
	url     string
	queue   chan AlertNotification
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
	closeMu sync.Mutex
	closed  bool
}

// NewTelegramSink builds a new Telegram alert dispatcher.
func NewTelegramSink(opts TelegramOptions) (*TelegramSink, error) {
	if strings.TrimSpace(opts.Token) == "" {
		return nil, errors.New("telegram: bot token must not be empty")
	}
	if strings.TrimSpace(opts.ChatID) == "" {
		return nil, errors.New("telegram: chat ID must not be empty")
	}

	timeout := opts.Timeout
	if timeout <= 0 {
		timeout = defaultTelegramTimeout
	}

	client := opts.Client
	if client == nil {
		client = &http.Client{Timeout: timeout}
	}

	retries := opts.MaxRetries
	if retries <= 0 {
		retries = defaultTelegramMaxRetries
	}

	qSize := opts.QueueSize
	if qSize <= 0 {
		qSize = defaultTelegramQueueSize
	}

	endpoint := opts.Endpoint
	if endpoint == "" {
		endpoint = fmt.Sprintf(defaultTelegramEndpoint, opts.Token)
	}

	opts.Timeout = timeout
	opts.MaxRetries = retries
	opts.QueueSize = qSize

	ctx, cancel := context.WithCancel(context.Background())

	s := &TelegramSink{
		opts:   opts,
		client: client,
		url:    endpoint,
		queue:  make(chan AlertNotification, qSize),
		ctx:    ctx,
		cancel: cancel,
	}

	s.wg.Add(1)
	go s.worker()

	return s, nil
}

func (s *TelegramSink) worker() {
	defer s.wg.Done()
	for {
		select {
		case <-s.ctx.Done():
			return
		case alert, ok := <-s.queue:
			if !ok {
				return
			}
			if err := s.Dispatch(context.Background(), alert); err != nil {
				select {
				case <-s.ctx.Done():
					return
				default:
				}
			}
		}
	}
}

// FormatTelegramMessage formats an alert into Markdown for Telegram.
func FormatTelegramMessage(alert AlertNotification) string {
	var sb strings.Builder
	sev := strings.ToUpper(alert.Severity)
	if sev == "" {
		sev = "ALERT"
	}

	fmt.Fprintf(&sb, "*🚨 [%s] %s*\n", sev, alert.RuleName)
	if alert.Message != "" {
		fmt.Fprintf(&sb, "%s\n\n", alert.Message)
	}
	if alert.LedgerSeq > 0 {
		fmt.Fprintf(&sb, "• *Ledger:* `%d`\n", alert.LedgerSeq)
	}
	if alert.TxHash != "" {
		fmt.Fprintf(&sb, "• *Tx Hash:* `%s`\n", alert.TxHash)
	}
	if alert.ContractID != "" {
		fmt.Fprintf(&sb, "• *Contract:* `%s`\n", alert.ContractID)
	}
	if !alert.Timestamp.IsZero() {
		fmt.Fprintf(&sb, "• *Time:* `%s`\n", alert.Timestamp.UTC().Format(time.RFC3339))
	}

	return sb.String()
}

// Dispatch sends an alert notification synchronously to Telegram with retries.
func (s *TelegramSink) Dispatch(ctx context.Context, alert AlertNotification) error {
	text := FormatTelegramMessage(alert)
	payload := map[string]interface{}{
		"chat_id":    s.opts.ChatID,
		"text":       text,
		"parse_mode": "Markdown",
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("telegram: marshaling payload: %w", err)
	}

	maxAttempts := s.opts.MaxRetries + 1
	var lastErr error

	for attempt := 1; attempt <= maxAttempts; attempt++ {
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.url, bytes.NewReader(body))
		if err != nil {
			return fmt.Errorf("telegram: building request: %w", err)
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("User-Agent", "stellar-prism")

		resp, err := s.client.Do(req)
		if err != nil {
			lastErr = err
		} else {
			respBytes, readErr := io.ReadAll(io.LimitReader(resp.Body, 1024))
			if readErr != nil {
				respBytes = nil
			}
			_ = resp.Body.Close()

			if resp.StatusCode >= 200 && resp.StatusCode < 300 {
				return nil
			}

			lastErr = fmt.Errorf("telegram api error HTTP %d: %s", resp.StatusCode, string(respBytes))
			// Only retry on 429 (rate limit) or 5xx server errors
			if resp.StatusCode != http.StatusTooManyRequests && resp.StatusCode < 500 {
				return lastErr
			}
		}

		if attempt < maxAttempts {
			delay := backoffDelay(100*time.Millisecond, 2*time.Second, attempt, 0.1)
			select {
			case <-ctx.Done():
				return ctx.Err()
			case <-time.After(delay):
			}
		}
	}

	return fmt.Errorf("telegram: delivery failed after %d attempts: %w", maxAttempts, lastErr)
}

// DispatchAsync queues an alert notification for non-blocking asynchronous dispatch.
func (s *TelegramSink) DispatchAsync(alert AlertNotification) bool {
	s.closeMu.Lock()
	defer s.closeMu.Unlock()
	if s.closed {
		return false
	}

	select {
	case s.queue <- alert:
		return true
	default:
		// Queue full, drop rather than blocking stream processing
		return false
	}
}

// Emit implements the stream sink interface by extracting event alerts.
func (s *TelegramSink) Emit(record stream.Record) error {
	alert := AlertNotification{
		RuleName:  "StreamEvent",
		Severity:  "info",
		LedgerSeq: record.Sequence,
		Timestamp: record.Time,
	}
	if record.Event != nil {
		alert.TxHash = record.Event.TxHash
		alert.ContractID = record.Event.ContractID
		alert.EventIndex = record.Event.EventIndex
		alert.Message = fmt.Sprintf("Event emitted by contract %s", record.Event.ContractID)
	} else {
		alert.Message = fmt.Sprintf("Ledger %d closed", record.Sequence)
	}

	s.DispatchAsync(alert)
	return nil
}

// Close shuts down the dispatcher worker cleanly.
func (s *TelegramSink) Close() error {
	s.closeMu.Lock()
	if s.closed {
		s.closeMu.Unlock()
		return nil
	}
	s.closed = true
	close(s.queue)
	s.closeMu.Unlock()

	s.cancel()
	s.wg.Wait()
	return nil
}
